#!/usr/bin/env python3
"""Reproduce the static phase-2 inventory; all generated bytes stay under tmp/."""
from pathlib import Path
import hashlib, json, os, re, struct
import _amigaxdev
from amigaxdev.disasm import dis
from amitools.binfmt.hunk.HunkReader import HunkReader
ROOT = Path(__file__).resolve().parents[1]
REPO = ROOT
GAME = ROOT/'tmp/game/TestDrive_v1.3_0089/TestDrive/data/TD'
OUT = ROOT/'tmp/phase2'

def main(manifest=ROOT/'manifest/phase2-inputs.sha256'):
    for line in manifest.read_text().splitlines():
        digest, name = line.split('  ', 1)
        p = Path(os.path.expandvars(name))
        if not p.is_absolute(): p = ROOT/p
        assert hashlib.sha256(p.read_bytes()).hexdigest() == digest, name
    b = GAME.read_bytes()
    assert hashlib.sha256(b).hexdigest() == 'dd5b9608d64de145a6138c99d175f148939bd8e8c37d793631314a50c9d606db'
    r = HunkReader()
    assert r.read_file(str(GAME)) == 0, r.error_string
    codes = [h for h in r.hunks if h['type_name'] == 'HUNK_CODE']
    assert [(h['data_file_offset'], h['size']) for h in codes] == [(0x28,0x7c0c),(0x9f78,0x1a28),(0xb9dc,0xa61c)]
    data = next(h['data'] for h in r.hunks if h['type_name'] == 'HUNK_DATA')
    assert len(data) == 0x1e94
    assert [h['size'] for h in r.hunks[0]['hunks']] == [0x7c0c,0x32a4,4]
    ov = next(h for h in r.hunks if h['type_name'] == 'HUNK_OVERLAY')
    assert ov['hunk_file_offset'] == 0x9f2c
    assert ov['ov_data'].hex() == '0000000200009f58028400100000b9bc029c001800030003000000000004001400000000'
    patches = {0x1d10:('PL_R','807c'),0x1cbc:('PL_R','13fc'),
        0x434:('PL_L','00bff002'),0x444:('PL_L','00bff096'),
        0x59a:('PL_S','48780001'),0x1872:('PL_PS','103900bfe001'),
        0x188a:('PL_PS','303900dff00c'),0x5402:('PL_PS','103900bfe001'),
        0x541a:('PL_PS','303900dff00c'),0x6390:('PL_P','4cdf4c004e75'),
        0x6916:('PL_P','4cdf1f074e75'),
        0x230:('PL_PS','4eac81464840'),0x5314:('PL_L','397900df'),
        0x5318:('PL_L','f0069bd8'),0x5334:('PL_W','3039'),0x5336:('PL_NOP','00dff006'),0x7aaa:('PL_PSS','226f00042c6c83d6')}
    source = (REPO/'src/TestDriveHD.s').read_text()
    actual = {(m,int(a,16)) for m,a in re.findall(r'^\s*(PL_\w+)\s+\$([0-9a-fA-F]+)',source,re.M)}
    assert actual == {(m,a) for a,(m,h) in patches.items()}, actual
    root = codes[0]['data']
    for a,(m,h) in patches.items(): assert root[a:a+len(bytes.fromhex(h))] == bytes.fromhex(h), hex(a)
    # Resolve a4-relative JMP entries, not TD2 addresses or relocation-dependent RAM.
    jumps = []
    for off in range(0,0x282,6):
        assert data[off:off+2] == b'\x4e\xf9'
        target = int.from_bytes(data[off+2:off+6],'big')
        assert target < len(root)
        jumps.append({'data_offset':off,'a4_displacement':off-0x7ffe,'root_target':target})
    for disp,target in [(0x81d6,0x7892),(0x827e,0x7b9a),(0x8146,0x530e),(0x8050,0xd44),(0x809e,0x10c4)]:
        assert int.from_bytes(data[disp-0x8002+2:disp-0x8002+6],'big') == target
    # Two 8-byte node records, with lists of (hunk number, stub count), ending in zero.
    table=ov['ov_data']; nodes=[]
    for n in range(2):
        fileoff, stub, desc = struct.unpack_from('>IHH',table,4+8*n)
        hn,count,zero=struct.unpack_from('>HHH',table,4+desc)
        assert zero == 0
        targets=[]
        for i in range(count):
            pos=stub+8*i; s=data[pos:pos+8]
            assert s[:2] == bytes.fromhex('6100') and s[4] == n+1
            targets.append(int.from_bytes(s[5:8],'big'))
        assert all(t < codes[n+1]['size'] for t in targets)
        nodes.append(dict(node=n+1,header_file_offset=fileoff,stub_data_offset=stub,hunk=hn,count=count,targets=targets))
    OUT.mkdir(parents=True,exist_ok=True)
    clean=[{k:(v.hex() if k=='ov_data' else len(v)) if isinstance(v,bytes) else v for k,v in h.items() if k!='data'} for h in r.hunks]
    (OUT/'hunks.json').write_text(json.dumps(clean,indent=2)+'\n')
    (OUT/'jump-table.json').write_text(json.dumps(jumps,indent=2)+'\n')
    (OUT/'overlay-nodes.json').write_text(json.dumps(nodes,indent=2)+'\n')
    ranges = {'root':[(0x42e,0x462),(0x588,0x626),(0xd44,0xd66),(0xe88,0xfa4),(0x10c4,0x11e6),(0x17e8,0x184e),(0x1872,0x18f2),(0x1cbc,0x1d1e),(0x2304,0x23e0),(0x26ae,0x26d0),(0x530e,0x5344),(0x53ec,0x544e),(0x62e0,0x6396),(0x641e,0x642c),(0x6892,0x697a),(0x7892,0x78aa),(0x7b9a,0x7ba2)],
      'overlay3':[(0,0x80)],'overlay4':[(0xa2a,0xc20),(0x10cc,0x1230),(0x1434,0x14de),(0x1a14,0x1b5a),(0x3796,0x39a8),(0x3b10,0x3c26),(0x7dfa,0x7eb6),(0x8594,0x863a),(0x869a,0x86aa)]}
    for label,h in zip(('root','overlay3','overlay4'),codes):
        p=OUT/(label+'.bin'); p.write_bytes(h['data'])
        (OUT/(label+'.disasm')).write_text(dis(str(p),0,0,len(h['data'])))
        (OUT/(label+'-excerpts.txt')).write_text('\n'.join(f'{label}:${s:05x}..${e:05x}\n'+dis(str(p),0,s,e) for s,e in ranges[label]))
    from audit_simulation import ranges, originals, validate
    verify_ranges=ranges();validate(verify_ranges,originals())
    report={'verify_ranges':len(verify_ranges),'game_sha256':hashlib.sha256(b).hexdigest(),'patches':len(patches),'root_jump_stubs':len(jumps),'nodes':nodes,'overlay_suffix_bytes':len(b)-0x9f2c,'overlay_code_bytes':sum(h['size'] for h in codes[1:]),'status':'PASS'}
    (OUT/'inventory-check.json').write_text(json.dumps(report,indent=2)+'\n')
    print(json.dumps(report,indent=2))
if __name__ == '__main__':
    import argparse
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--manifest',type=Path,default=ROOT/'manifest/phase2-inputs.sha256')
    parser.add_argument('--out',type=Path,default=OUT)
    args=parser.parse_args();OUT=args.out;OUT.mkdir(parents=True,exist_ok=True)
    main(args.manifest)
